/**
 * Original design by Gustavo Fior (@gustavo-fior), co-founder Abdul Haidar, and Foglamp Labs.
 * Extracted AS-IS from foglamp-labs/foglamp: apps/web/src/components/marketing/landing/ask-foggy.tsx.
 * Licensed under Apache-2.0.
 */
"use client";

import { Button } from "../../../ui/button";
import { TextShimmerLoader } from "../../../ui/loader";
import {
	IconArrowRight,
	IconPlayerStopFilled,
} from "@tabler/icons-react";
import { useRef, useState } from "react";
import { Streamdown } from "streamdown";

import { markdownComponents } from "../../../widgets/markdown";

// The last row of the FAQ. The request itself is supplied by the host so the
// component can render inside any app without owning an API endpoint.

export type AskFoggyRequest = (
	question: string,
	options: { signal: AbortSignal },
) => AsyncIterable<string>;

export type AskFoggyProps = {
	onAsk?: AskFoggyRequest;
};

function errorMessage(error: unknown): string {
	if (error instanceof Error) {
		try {
			const parsed: unknown = JSON.parse(error.message);
			if (
				typeof parsed === "object" &&
				parsed !== null &&
				"error" in parsed &&
				typeof parsed.error === "string"
			) {
				return parsed.error;
			}
		} catch {
			// Use the generic line for non-JSON errors.
		}
	}
	return "Foggy hit a snag. Please try again in a moment.";
}

export function AskFoggy({ onAsk }: AskFoggyProps) {
	const [input, setInput] = useState("");
	const [answerText, setAnswerText] = useState("");
	const [error, setError] = useState<string | null>(null);
	const [busy, setBusy] = useState(false);
	const abortRef = useRef<AbortController | null>(null);

	const stop = () => {
		abortRef.current?.abort();
	};

	const submit = async (event: React.FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		const question = input.trim();
		if (!question || busy) return;
		if (!onAsk) {
			setError("Connect an onAsk handler to enable Foggy responses.");
			return;
		}

		const controller = new AbortController();
		abortRef.current = controller;
		setBusy(true);
		setError(null);
		setAnswerText("");
		try {
			for await (const chunk of onAsk(question, { signal: controller.signal })) {
				if (controller.signal.aborted) break;
				setAnswerText((current) => current + chunk);
			}
		} catch (caught) {
			if (!controller.signal.aborted) setError(errorMessage(caught));
		} finally {
			if (abortRef.current === controller) abortRef.current = null;
			setBusy(false);
		}
	};

	// Only the latest answer is shown. The question stays in the input above it,
	// so the pair reads like any other row on the list.
	const thinking = busy && !answerText;

	return (
		<div>
			<form
				// The button is 32px in a 24px line. The negative margin keeps this row
				// the same 64px as the question rows above it.
				className="flex items-center gap-4 border-b border-border/70 py-5"
				onSubmit={(event) => void submit(event)}
			>
				<label htmlFor="ask-foggy" className="sr-only">
					Ask Foggy a question about Foglamp
				</label>
				<input
					id="ask-foggy"
					value={input}
					onChange={(event) => setInput(event.target.value)}
					placeholder="Ask anything else"
					maxLength={600}
					autoComplete="off"
					className="min-w-0 flex-1 bg-transparent text-base outline-none placeholder:text-muted-foreground"
				/>
				{busy ? (
					<Button
						type="button"
						size="icon-sm"
						variant="secondary"
						className="-my-1"
						aria-label="Stop"
						onClick={stop}
					>
						<IconPlayerStopFilled />
					</Button>
				) : (
					<Button
						type="submit"
						size="icon-sm"
						className="-my-1"
						aria-label="Send"
						disabled={!input.trim()}
						variant={!input.trim() ? "ghost" : "secondary"}
					>
						<IconArrowRight strokeWidth={3} />
					</Button>
				)}
			</form>

			{/* Always rendered with a floor, so the answer does not push the page
			    around when it arrives. Long answers still grow past it. */}
			<div className="min-h-60 pt-5 pb-6 text-[15px] leading-relaxed [&_a]:underline [&_a]:decoration-[0.5px] [&_a]:underline-offset-3 [&_a]:hover:text-foreground [&_li]:my-0.5 [&_ol]:my-1.5 [&_ol]:list-decimal [&_ol]:pl-5 [&_p]:my-1.5 [&_pre]:my-2 [&_ul]:my-1.5 [&_ul]:list-disc [&_ul]:pl-5 *:first:mt-0 *:last:mb-0">
				{thinking && <TextShimmerLoader text="Reading the docs" size="md" />}
				{answerText && (
					<Streamdown components={markdownComponents} controls={{ table: false }}>
						{answerText}
					</Streamdown>
				)}
				{error && <p className="text-destructive">{error}</p>}
			</div>
		</div>
	);
}

/**
 * Original design by Gustavo Fior (@gustavo-fior), co-founder Abdul Haidar, and Foglamp Labs.
 * Extracted AS-IS from foglamp-labs/foglamp: apps/web/src/components/marketing/landing/faq.tsx.
 * Licensed under Apache-2.0.
 */
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "../../../ui/accordion";

import { AskFoggy } from "./ask-foggy";
import type { AskFoggyRequest } from "./ask-foggy";
import { Button } from "../../../ui/button";

const DOCS_ORIGIN = "https://docs.foglamp.dev";
const GITHUB_URL = "https://github.com/foglamp-labs/foglamp";

// Six questions, hairline rows, and under them a public Foggy that answers
// everything else from the docs. Answers are also emitted as FAQPage JSON-LD
// so search engines can lift them.

type Faq = { q: string; a: string; links?: { label: string; href: string }[] };

const FAQS: Faq[] = [
  {
    q: "What is Foglamp?",
    a: "Observability for AI agents built on the Vercel AI SDK. Every generateText and streamText call becomes a trace with its cost, latency, tokens, prompt, and response. Evals score what your agents say, and alerts watch cost, errors, and pass rates. It is open source and you can run it yourself.",
    links: [{ label: "Read the docs", href: DOCS_ORIGIN }],
  },
  {
    q: "Which AI SDK versions are supported?",
    a: "Versions 4 through 6 use wrap() from foglamp/wrap around your model calls. Version 7 uses the native telemetry integration: registerTelemetry(foglamp()) once at startup. The setup prompt reads your installed version and picks the right path.",
    links: [
      { label: "Instrumentation guide", href: `${DOCS_ORIGIN}/ai-instrument` },
    ],
  },
  {
    q: "Can I self-host it?",
    a: "Yes. Foglamp is Apache 2.0 and ships with a docker compose file that brings up the app, Postgres, and ClickHouse. Nothing in the self-hosted version phones home.",
    links: [
      { label: "Self-hosting guide", href: `${DOCS_ORIGIN}/self-hosting` },
      { label: "GitHub", href: GITHUB_URL },
    ],
  },
  {
    q: "Where are my prompts and responses stored?",
    a: "In ClickHouse, scoped to your project, for as long as your plan retains data: 3 days on Free and 14 days on Pro. If you self-host, all of it stays on your own infrastructure. PII redaction in the SDK is on the roadmap.",
    links: [{ label: "Privacy policy", href: "/privacy" }],
  },
  {
    q: "What does the SDK add to my request latency?",
    a: "Nothing on the request path. Spans are batched in memory and flushed in the background every five seconds. On serverless, call flush() before the function returns. If Foglamp is unreachable, your agent keeps running and the batch is dropped.",
    links: [{ label: "SDK reference", href: `${DOCS_ORIGIN}/sdk` }],
  },
];

const faqJsonLd = {
  "@context": "https://schema.org",
  "@type": "FAQPage",
  mainEntity: FAQS.map((f) => ({
    "@type": "Question",
    name: f.q,
    acceptedAnswer: { "@type": "Answer", text: f.a },
  })),
};

export function Faq({ onAsk }: { onAsk?: AskFoggyRequest } = {}) {
  return (
    <section
      id="faq"
      className="mx-auto mt-32 w-full max-w-7xl px-5 sm:mt-40 sm:px-8"
    >
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify(faqJsonLd).replace(/</g, "\\u003c"),
        }}
      />
      <div className="grid gap-10 lg:grid-cols-[1fr_2fr] lg:gap-20">
        <header>
          <h2 className="font-display text-3xl font-[450] tracking-tight text-balance sm:text-4xl">
            Questions
          </h2>
          <p className="mt-3 max-w-xs text-muted-foreground text-pretty">
            The short ones are here. For anything else, ask Foggy below.
          </p>
        </header>

        <div className="-mt-4">
          <Accordion>
            {FAQS.map((f) => (
              <AccordionItem
                key={f.q}
                value={f.q}
                className="border-b border-border/70 last:border-b"
              >
                <AccordionTrigger className="rounded-none border-0 py-5 text-base cursor-pointer hover:opacity-70 font-normal hover:no-underline">
                  {f.q}
                </AccordionTrigger>
                <AccordionContent className="pb-8 text-[15px] leading-relaxed text-muted-foreground">
                  <p>{f.a}</p>
                  {f.links && (
                    <div className="flex flex-wrap gap-x-2.5 gap-y-1 text-sm mt-5">
                      {f.links.map((l) => (
                        <a
                          key={l.href}
                          href={l.href}
                          {...(l.href.startsWith("http")
                            ? { target: "_blank", rel: "noreferrer" }
                            : {})}
                        >
                          <Button variant="secondary">{l.label}</Button>
                        </a>
                      ))}
                    </div>
                  )}
                </AccordionContent>
              </AccordionItem>
            ))}
          </Accordion>

          <AskFoggy onAsk={onAsk} />
        </div>
      </div>
    </section>
  );
}

"use client";

/**
 * Original design by Gustavo Fior (@gustavo-fior) and Foglamp Labs,
 * co-founded by Abdul Haidar. Extracted AS-IS from foglamp-labs/foglamp.
 */

import * as React from "react";

type FoglampLinkComponent = React.ElementType;

const FoglampLinkContext = React.createContext<FoglampLinkComponent>("a");

export type FoglampLinkProviderProps = {
	/** Router or link component that should render every FoglampLink below it. */
	component: FoglampLinkComponent;
	children: React.ReactNode;
};

export function FoglampLinkProvider({
	component,
	children,
}: FoglampLinkProviderProps) {
	return (
		<FoglampLinkContext.Provider value={component}>
			{children}
		</FoglampLinkContext.Provider>
	);
}

/**
 * A link with no wrapper of its own. The provider component receives the
 * original props directly, so the rendered DOM and styling stay with the
 * router's link implementation. A per-link component or `as` can override it.
 */
export type FoglampLinkProps<Component extends FoglampLinkComponent = "a"> =
	React.ComponentPropsWithRef<Component> & {
		component?: Component;
		as?: Component;
		/** Common router destination prop, available with the default anchor type. */
		to?: string;
	};

export function FoglampLink<Component extends FoglampLinkComponent = "a">({
	component,
	as,
	...props
}: FoglampLinkProps<Component>) {
	const providerComponent = React.useContext(FoglampLinkContext);
	const LinkComponent = component ?? as ?? providerComponent;

	return React.createElement(LinkComponent, props as React.ComponentPropsWithRef<Component>);
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/packages/ui/src/lib/utils.ts; derived here under Apache-2.0.
 */
export { cn } from "cn";

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/packages/ui/src/components/accordion.tsx; derived here under Apache-2.0.
 */
import { Accordion as AccordionPrimitive } from "@base-ui/react/accordion";

import { cn } from "../lib/utils";
import { IconChevronDown } from "@tabler/icons-react";

function Accordion({ className, ...props }: AccordionPrimitive.Root.Props) {
  return (
    <AccordionPrimitive.Root
      data-slot="accordion"
      className={cn("flex w-full flex-col", className)}
      {...props}
    />
  );
}

function AccordionItem({ className, ...props }: AccordionPrimitive.Item.Props) {
  return (
    <AccordionPrimitive.Item
      data-slot="accordion-item"
      className={cn("not-last:border-b", className)}
      {...props}
    />
  );
}

function AccordionTrigger({
  className,
  children,
  ...props
}: AccordionPrimitive.Trigger.Props) {
  return (
    <AccordionPrimitive.Header className="flex">
      <AccordionPrimitive.Trigger
        data-slot="accordion-trigger"
        className={cn(
          "group/accordion-trigger relative flex flex-1 items-start justify-between rounded-md border border-transparent py-4 text-left text-sm font-medium outline-none hover:underline focus-visible:border-ring focus-visible:ring-[1.5px] focus-visible:ring-ring/50 focus-visible:after:border-ring aria-disabled:pointer-events-none pr-2 aria-disabled:opacity-50 **:data-[slot=accordion-trigger-icon]:ml-auto **:data-[slot=accordion-trigger-icon]:size-4 **:data-[slot=accordion-trigger-icon]:text-muted-foreground",
          className
        )}
        {...props}
      >
        {children}
        <IconChevronDown
          data-slot="accordion-trigger-icon"
          className="pointer-events-none shrink-0 group-aria-expanded/accordion-trigger:rotate-180 transition-transform duration-300"
        />
      </AccordionPrimitive.Trigger>
    </AccordionPrimitive.Header>
  );
}

function AccordionContent({
  className,
  children,
  ...props
}: AccordionPrimitive.Panel.Props) {
  return (
    // Height transitions on Base UI's measured panel height: 0 in the
    // starting/ending styles, the measured value in between. The curve is a
    // fast-out, long-settle ease (same one the landing hero uses) so the panel
    // decelerates into place rather than the default ease-out's flat finish.
    // The content inside fades on the same clock, so it doesn't sit fully
    // opaque in a sliver of panel at either end.
    <AccordionPrimitive.Panel
      data-slot="accordion-content"
      className="group/accordion-content h-(--accordion-panel-height) overflow-hidden text-sm transition-[height] duration-300 ease-[cubic-bezier(0.22,1,0.36,1)] data-ending-style:h-0 data-starting-style:h-0"
      {...props}
    >
      <div
        className={cn(
          "pt-0 pb-4 transition-opacity duration-300 ease-[cubic-bezier(0.22,1,0.36,1)] group-data-ending-style/accordion-content:opacity-0 group-data-starting-style/accordion-content:opacity-0 [&_a]:underline [&_a]:underline-offset-3 [&_a]:hover:text-foreground [&_p:not(:last-child)]:mb-4",
          className
        )}
      >
        {children}
      </div>
    </AccordionPrimitive.Panel>
  );
}

export { Accordion, AccordionContent, AccordionItem, AccordionTrigger };

/**
 * Original design by Gustavo Fior (@gustavo-fior) and Foglamp Labs,
 * co-founded by Abdul Haidar. Extracted AS-IS from foglamp-labs/foglamp.
 */

import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { type VariantProps, cva } from "class-variance-authority";
import * as React from "react";

import { cn } from "../lib/utils";

const buttonVariants = cva(
  "group/button inline-flex shrink-0 cursor-pointer items-center justify-center rounded-full bg-clip-padding text-sm font-medium whitespace-nowrap transition-all hover:duration-150 outline-none select-none focus-visible:border-ring focus-visible:ring-[1.5px] focus-visible:ring-ring/50 active:scale-[0.97] disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-[1.5px] aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-3.5",
  {
    variants: {
      variant: {
        default:
          "bg-neutral-800 dark:bg-neutral-100 shadow-[var(--custom-shadow-primary)] text-primary-foreground hover:bg-primary/80 dark:hover:bg-primary/90 [&_svg:not([class*='text-'])]:text-neutral-300 dark:[&_svg:not([class*='text-'])]:text-neutral-700",
        outline:
          "shadow-(--custom-outline-shadow) bg-background hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:bg-card dark:hover:bg-muted [&_svg:not([class*='text-'])]:text-neutral-500 dark:[&_svg:not([class*='text-'])]:text-neutral-400",
        secondary:
          "bg-secondary shadow-[var(--custom-shadow-secondary)] text-secondary-foreground hover:bg-secondary/80 aria-expanded:bg-secondary aria-expanded:text-secondary-foreground dark:hover:bg-muted-foreground/25 [&_svg:not([class*='text-'])]:text-neutral-500 dark:[&_svg:not([class*='text-'])]:text-neutral-300",
        ghost:
          "hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground [&_svg:not([class*='text-'])]:text-neutral-500 dark:[&_svg:not([class*='text-'])]:text-neutral-400",
        // Like `ghost` (transparent at rest), but hover tints it red — bg and
        // icon/text both shift to the destructive color. For low-emphasis
        // delete affordances that only "arm" on hover.
        "ghost-destructive":
          "hover:bg-destructive/10 hover:text-destructive text-destructive focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:hover:bg-destructive/20 dark:focus-visible:ring-destructive/40",
        destructive:
          "bg-destructive/10 shadow-[var(--custom-shadow-destructive)] text-destructive hover:bg-destructive/20 focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:hover:bg-destructive/30 dark:focus-visible:ring-destructive/40",
        // Underline stays rendered but transparent at rest, fading its opacity
        // in on hover — the base `transition-all` animates the decoration color.
        link: "text-foreground underline decoration-foreground/20 underline-offset-4 hover:decoration-foreground",
      },
      size: {
        xs: "h-6 gap-[4.5px] rounded-full px-2.5 text-xs in-data-[slot=button-group]:rounded-full has-[>svg:first-child]:pl-2 has-[>svg:last-child]:pr-2 [&_svg:not([class*='size-'])]:size-[11px]",
        sm: "h-7 gap-[5px] rounded-full px-3 in-data-[slot=button-group]:rounded-full has-[>svg:first-child]:pl-[9px] has-[>svg:last-child]:pr-[9px]",
        default:
          "h-8 gap-[5.5px] px-3 in-data-[slot=button-group]:rounded-full has-[>svg:first-child]:pl-2.5 has-[>svg:last-child]:pr-2.5",
        lg: "h-8.5 gap-1.5 px-[15px] has-[>svg:first-child]:pl-3 has-[>svg:last-child]:pr-3 [&_svg:not([class*='size-'])]:size-3.5",
        icon: "size-8",
        "icon-xs":
          "size-6 rounded-full in-data-[slot=button-group]:rounded-full [&_svg:not([class*='size-'])]:size-3",
        "icon-sm":
          "size-8 rounded-full in-data-[slot=button-group]:rounded-full",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

function Button({
  className,
  variant = "default",
  size = "default",
  children,
  nativeButton,
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof buttonVariants>) {
  return (
    <ButtonPrimitive
      data-slot="button"
      className={cn(buttonVariants({ variant, size, className }))}
      // When `render` swaps in a non-button element (e.g. a Next.js
      // <Link>/<a>), it isn't a native <button>; tell Base UI so it applies the
      // right a11y semantics instead of warning. An explicit prop always wins.
      nativeButton={nativeButton ?? props.render === undefined}
      {...props}
    >
      {React.Children.map(children, (child) =>
        typeof child === "string" || typeof child === "number" ? (
          <span>{child}</span>
        ) : (
          child
        )
      )}
    </ButtonPrimitive>
  );
}

export { Button, buttonVariants };

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/packages/ui/src/components/loader.tsx; derived here under Apache-2.0.
 */
import { cn } from "../lib/utils";

// prompt-kit "text-shimmer" loader (https://www.prompt-kit.com/docs/loader):
// a label whose color sweeps left→right via an animated background-clip gradient.
// Relies on the `shimmer` keyframes + `--animate-shimmer` registered in
// styles/globals.css.

export type TextShimmerLoaderProps = {
	text?: string;
	size?: "sm" | "md" | "lg";
	className?: string;
};

const textSizes = {
	sm: "text-xs",
	md: "text-sm",
	lg: "text-base",
} as const;

export function TextShimmerLoader({
	text = "Thinking",
	size = "md",
	className,
}: TextShimmerLoaderProps) {
	return (
		<div
			role="status"
			aria-label={text}
			className={cn(
				"bg-[linear-gradient(to_right,var(--muted-foreground)_40%,var(--foreground)_60%,var(--muted-foreground)_80%)]",
				"bg-clip-text font-normal text-transparent bg-size-[200%_auto]",
				"animate-shimmer",
				textSizes[size],
				className,
			)}
		>
			{text}
		</div>
	);
}

/** Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted AS-IS from .reference/foglamp/apps/web/src/components/app/markdown.tsx; derived under Apache-2.0.
 */
import { FoglampLink } from "../lib/link-context";
import type { ComponentProps } from "react";

// Shared Streamdown component overrides for rendering model markdown across the
// app (Foggy chat, session transcripts, …). Pass as `components` to <Streamdown>.
export const markdownComponents = {
	// Route relative links (e.g. `/traces/abc`) through the host-provided FoglampLink for in-app nav;
	// open absolute links (docs, external) in a new tab.
	a: ({ href = "", children, ...rest }: ComponentProps<"a">) => {
		if (href.startsWith("/")) {
			return (
				<FoglampLink
					href={href}
					className="font-medium text-primary underline underline-offset-2"
				>
					{children}
				</FoglampLink>
			);
		}
		return (
			<a
				{...rest}
				href={href}
				target="_blank"
				rel="noreferrer"
				className="font-medium text-primary underline underline-offset-2"
			>
				{children}
			</a>
		);
	},
	// Flat, chat-native tables — replaces Streamdown's bordered card + toolbar.
	// The wrapper scrolls horizontally so wide tables never break the layout.
	table: ({ children }: ComponentProps<"table">) => (
		<div className="my-3 w-full overflow-x-auto rounded-md squircle:rounded-xl corner-squircle border border-border/60">
			<table className="w-full border-collapse text-xs tabular-nums">
				{children}
			</table>
		</div>
	),
	thead: ({ children }: ComponentProps<"thead">) => (
		<thead className="bg-muted/40 text-muted-foreground">{children}</thead>
	),
	tr: ({ children }: ComponentProps<"tr">) => (
		<tr className="border-b border-border/40 last:border-0">{children}</tr>
	),
	th: ({ children }: ComponentProps<"th">) => (
		<th className="px-3 py-2 text-left font-medium whitespace-nowrap">
			{children}
		</th>
	),
	td: ({ children }: ComponentProps<"td">) => (
		<td className="px-3 py-1.5 align-top">{children}</td>
	),
	// Streamdown wraps images in a <div> for its hover controls, but markdown puts
	// images inside paragraphs — a <div> inside a <p> is invalid HTML, and React
	// throws a hydration error on it. A bare <img> is valid wherever an image can
	// legally appear, so it renders the same in every context.
	img: ({ src, alt, ...rest }: ComponentProps<"img">) => (
		// Deliberately not an image optimizer: these are arbitrary remote URLs from model
		// output, not assets the optimizer can be pointed at.
		<img
			{...rest}
			src={typeof src === "string" ? src : undefined}
			alt={alt ?? ""}
			className="my-1.5 inline-block max-h-64 max-w-full rounded-md"
		/>
	),
	hr: () => <hr className="my-3 border-border/60" />,
};
